function RubySentence({hanzi,pinyin}:{hanzi:string;pinyin:string}){const cleaned=cleanPinyin(pinyin);const characters=[...hanzi].filter(char=>/[\u3400-\u9fff]/.test(char));const syllables=splitPinyin(cleaned,characters.length);if(!syllables.length||syllables.length!==characters.length)return <RubyPhraseFallback hanzi={hanzi} pinyin={cleaned}/>;let index=0;return <span className="phrase-ruby">{[...hanzi].map((char,charIndex)=>/[\u3400-\u9fff]/.test(char)?<ruby key={`${char}-${charIndex}`}><rt>{syllables[index++]}</rt><span>{char}</span></ruby>:<span className={/[，。！？；：,.!?;:]/.test(char)?'phrase-punctuation':undefined} key={`${char}-${charIndex}`}>{char}</span>)}</span>}
