  const h=hanzi.map(item=>({id:`h-${item.id}`,front:item.char,back:language==='es'?item.meaningSpanish||t(language,'Meaning unavailable','Significado no disponible'):item.meaningEnglish||t(language,'Meaning unavailable','Meaning unavailable'),detail:'',audio:item.char,pronunciation:pronunciationFor(item.char)}));
