type FlashItem={id:string;front:string;back:string;detail:string;audio:string;pronunciation:string;examples?:string[]};
function FlashcardsView({lesson,language,mode,setMode,index,setIndex,flipped,setFlipped}:{lesson:number;language:Language;mode:'hanzi'|'words'|'phrases'|'grammar'|'mix';setMode:(mode:'hanzi'|'words'|'phrases'|'grammar'|'mix')=>void;index:number;setIndex:(index:number)=>void;flipped:boolean;setFlipped:(value:boolean)=>void}){const words=data.vocabulary.filter(item=>item.lesson===lesson);const hanzi=data.hanzi.filter(item=>item.lesson===lesson);const phrases=data.grammarPhrases.filter(item=>item.lesson===lesson);const grammar=data.grammar.filter(item=>item.lesson===lesson);const pronunciationFor=(char:string)=>pronunciationForHanzi(char).join(' / ');const build=(kind:typeof mode):FlashItem[]=>{const h=hanzi.map(item=>{const pronunciation=pronunciationFor(item.char);return {id:`h-${item.id}`,front:item.char,back:'',detail:'',audio:item.char,pronunciation}});const w=words.map(item=>({id:item.id,front:item.hanzi,back:item.english,detail:item.pos,audio:item.hanzi,pronunciation:item.pinyin}));const p=phrases.map(item=>({id:item.id,front:item.hanzi,back:item.english||t(language,'Phrase meaning','Significado de la frase'),detail:item.source,audio:item.hanzi,pronunciation:item.pinyin}));const g=grammar.map(item=>({id:item.id,front:item.point,back:item.name,detail:item.formula,audio:item.examples.split('\\n')[0]||item.point,pronunciation:''}));if(kind==='hanzi')return h;if(kind==='words')return w;if(kind==='phrases')return p;if(kind==='grammar')return g;return [...h,...w,...p,...g]};const items=build(mode);const card=items[index%Math.max(1,items.length)];const touchStart=useRef<number|null>(null);const changeCard=(delta:number)=>{if(!items.length)return;setIndex((index+delta+items.length)%items.length);setFlipped(false)};useEffect(()=>{const handleKey=(event:KeyboardEvent)=>{if(event.key==='ArrowLeft'){event.preventDefault();changeCard(-1)}else if(event.key==='ArrowRight'){event.preventDefault();changeCard(1)}};window.addEventListener('keydown',handleKey);return()=>window.removeEventListener('keydown',handleKey)},[items.length,index]);const labels={hanzi:t(language,'Hanzi','Caracteres'),words:t(language,'Words','Palabras'),phrases:t(language,'Phrases','Frases'),grammar:t(language,'Grammar','Gramática')};const tabs=Object.keys(labels) as Array<keyof typeof labels>;if(!card)return <div className="empty-state"><strong>{t(language,'No cards available.','No hay tarjetas disponibles.')}</strong></div>;return <div className="flash-area"><div className="flash-mode-tabs">{tabs.map(item=><button key={item} className={mode===item?'active':''} onClick={()=>{setMode(item);setIndex(0);setFlipped(false)}}>{labels[item]}</button>)}</div><div className={'flashcard '+(flipped?'is-flipped':'')} onClick={()=>setFlipped(!flipped)} role="button" tabIndex={0} onKeyDown={e=>e.key==='Enter'&&setFlipped(!flipped)} onTouchStart={event=>{touchStart.current=event.touches[0]?.clientX??null}} onTouchEnd={event=>{if(touchStart.current===null)return;const distance=event.changedTouches[0].clientX-touchStart.current;touchStart.current=null;if(Math.abs(distance)>45)changeCard(distance<0?1:-1)}}><div className="flash-front"><strong>{card.front}</strong></div><div className="flash-back">{card.back&&<h3>{card.back}</h3>}{card.pronunciation&&<button className="flash-pronunciation" aria-label={t(language,'Play pronunciation','Reproducir pronunciación')} onClick={e=>{e.stopPropagation();speak(card.audio)}}>{card.pronunciation}</button>}{card.detail&&<p>{card.detail}</p>}</div></div><div className="flash-actions"><button className="secondary flash-nav-button" aria-label={t(language,'Previous card','Tarjeta anterior')} onClick={()=>changeCard(-1)}><ChevronLeft size={18}/></button><span>{(index%items.length)+1} / {items.length}</span><button className="secondary flash-nav-button" aria-label={t(language,'Next card','Siguiente tarjeta')} onClick={()=>changeCard(1)}><ChevronRight size={18}/></button></div></div>}
